    ('aws-key',         re.compile(r'\bAKIA[0-9A-Z]{16}\b')),
    ('gitlab-pat',      re.compile(r'\bglpat-[A-Za-z0-9_\-]{20,}')),
    ('private-key',     re.compile(r'-----BEGIN [A-Z ]*PRIVATE KEY-----')),
    ('api-key-assign',  re.compile(r'(?i)\b(?:api[_-]?key|auth[_-]?token|access[_-]?token)"?\s*[:=]\s*"?[A-Za-z0-9_\-]{24,}')),
    ('bearer',          re.compile(r'(?i)\bBearer\s+[A-Za-z0-9_\-\.]{24,}')),
    ('hex48',           re.compile(r'\b[0-9a-f]{48}\b')),
    ('jwt',             re.compile(r'\beyJ[A-Za-z0-9_\-]{10,}\.[A-Za-z0-9_\-]{10,}\.')),
]

targets = sorted(pathlib.Path('agent-sessions').glob('*.jsonl')) + \
          sorted(pathlib.Path.home().glob('.claude/projects/-Users-ivan-tkachenko-Projects-test-lastunit/*.jsonl'))

print(f"scanning {len(targets)} files for {len(pats)} patterns + {len(env_secrets)} live .env secrets\n")
any_hit = False
for f in targets:
    hits = collections.Counter()
    with f.open(encoding='utf-8', errors='replace') as fh:
        for i, line in enumerate(fh, 1):
            for name, rx in pats:
                if rx.search(line):
                    hits[name] += 1
            for k, v in env_secrets.items():
                if v in line:
                    hits[f'LIVE:{k}'] += 1
    label = ('repo  ' if 'agent-sessions' in str(f) else 'source') + '  ' + f.name[:44]
    if hits:
        any_hit = True
        print(f"!! {label}")
        for k, c in hits.most_common():
            print(f"       {k}: {c} line(s)")
    else:
        print(f"ok {label}")
print("\nNO MATCHES ANYWHERE" if not any_hit else "\n^^ review the flagged files")
